for _e in _EQUITY:
    _sym = _e["symbol"]
    _e["sector"] = _SECTOR.get(_sym, _e.get("sector") or "Diversified")
    _e["score_is_estimate"] = _sym in _SCORE_EST
    if _sym in _SCORE_EST:
        _e["ionic_score"] = _SCORE_EST[_sym]
        _e["score_3y"] = _SCORE_EST[_sym]
        _e["score_1y"] = _SCORE_EST[_sym]
    # 2026-08-03 full-750 research completion: real quant+analyst score, sets score AND
    # rec AND client_case together (never as separate steps -- Talaulikar-build lesson)
    if _sym in _SCORE_750:
        _e["ionic_score"], _e["score_3y"], _e["score_1y"], _e["rec"], _e["client_case"] = _SCORE_750[_sym]
    # Unscored stocks: keep ionic_score as None (never show 0)
    if _e.get("ionic_score") is None:
        _e["rec"] = "No View"
    if _e.get("score_3y") is None:
        _e["score_3y"] = _e.get("ionic_score")
    if _e.get("score_1y") is None:
        _e["score_1y"] = _e.get("ionic_score")
    _e["sell_reason_type"] = "quality"
    if _sym in _MRS_T_LIQ:
        _e["rec"], _e["client_case"] = _MRS_T_LIQ[_sym]
        _e["sell_reason_type"] = "liquidity"
    _e.setdefault("pe", None); _e.setdefault("roe", None)
    # Mcap band from lookup
    if _sym in _MCAP_LARGE:
        _e["mcap_band"] = "Large"
    elif _sym in _MCAP_MID:
        _e["mcap_band"] = "Mid"
    else:
        _e["mcap_band"] = "Small"
    _e.setdefault("growth_pct", None)
    _e.setdefault("positive", ""); _e.setdefault("negative", _e.get("summary", ""))
    _e.setdefault("reverse_dcf", "")
    _e.setdefault("reason_category", "" if _e["rec"] not in ("Sell", "Trim") else "Weaker forward risk-reward")
    _sc = _e.get("ionic_score")
    _e.setdefault("conviction", "Core" if (_sc or 0) >= 58 else ("Watch" if _e["rec"] in ("Hold", "No View") else "Exit"))
    _e.setdefault("holding_years", 2.0)
    _e.setdefault("pit_date", "2026-07-31")
    _e.setdefault("invested_value", None)
    if not _e.get("client_case"):
        _scrubbed = _scrub_client_text(_e.get("summary", ""))
        if _e["rec"] == "No View":
            _e["client_case"] = "Outside our current scored universe; pending research scoring."
        elif _sc is not None:
            _e["client_case"] = _scrubbed or (
                f"Scores {_sc:.0f}/100 on our quality/value/momentum framework, "
                + ("below our bar; recommended for exit." if _e["rec"] == "Sell"
                   else "comfortably within our Hold range; no changes recommended this review."))
        else:
            _e["client_case"] = _scrubbed or (
                "Analyst-reviewed; " + ("recommended for exit." if _e["rec"] == "Sell"
                   else "no changes recommended this review."))
    _e["analyst_read"] = _e["client_case"][:150]
    _e["detailed"] = _e["client_case"]
    _e["negative"] = _e.get("negative_para") or _e["client_case"]
    if _e["rec"] in ("Sell", "Trim"):
        _e.setdefault("binding_trigger", _e["client_case"][:130])
    else:
        _e.setdefault("binding_trigger", "")


